/* eslint-disable @typescript-eslint/no-unused-vars -- shared helpers, pasted in front of the Code nodes that use them */
/**
 * Shared helpers, pasted by pack-workflows.mjs in front of every Code node that needs them:
 * addresses, query strings, escaping, slugs, Strapi admin links, and the one page layout
 * with navigation used by all review pages. Nothing here talks to an API.
 */

const CMS = "https://cms.beer.de";
// Links to the website go to staging until the new site is live on beer.de.
const SITE = "https://staging.beer.de";

const qs = (query) =>
  Object.entries(query)
    .filter(([, value]) => value !== undefined && value !== null)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join("&");

const esc = (value) =>
  String(value ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

const slugify = (value, max = 60) =>
  String(value ?? "")
    .toLowerCase()
    .replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, max)
    .replace(/-$/, "");

const UID = {
  projects: "api::project.project",
  articles: "api::article.article",
  "site-pages": "api::site-page.site-page",
  "kitchen-topics": "api::kitchen-topic.kitchen-topic",
  regions: "api::region.region",
  materials: "api::material.material",
  appliances: "api::appliance.appliance",
  brands: "api::brand.brand",
  "furniture-items": "api::furniture-item.furniture-item",
};
const adminUrl = (api, documentId, locale = "de") =>
  `${CMS}/admin/content-manager/collection-types/${UID[api] ?? api}/${documentId}?plugins[i18n][locale]=${locale}`;

const when = (iso) => (iso ? new Date(iso).toLocaleString("de-DE", { timeZone: "Europe/Berlin", dateStyle: "medium", timeStyle: "short" }) : "");

// Same words as the website uses for a "useful" photo description.
const weakAlt = (alt) => {
  const text = String(alt ?? "").trim();
  return text.length < 30 || !text.includes(" ") || /\.(jpe?g|png|webp|gif)$/i.test(text);
};

const NAV = [
  ["Übersicht", "/webhook/redaktion"],
  ["SEO-Prüfung", "/webhook/seo-pruefung"],
  ["SEO-Vorschläge", "/webhook/seo-vorschlaege"],
  ["Projekttexte", "/webhook/beer-texte"],
  ["Ratgeber", "/webhook/beer-ratgeber"],
  ["GEO-Monitor", "/webhook/geo-monitor"],
  ["Regionen", "/webhook/beer-regionen"],
  ["Meldungen", "/webhook/0b1c2d3e-4f5a-4b6c-8d7e-9f0a1b2c3d06/chat"],
  ["Neue Seite", "/webhook/7d8e9f0a-1b2c-4d3e-8f4a-5b6c7d8e9f07/chat"],
];

/** One full HTML page in the shared layout. `active` is the NAV label to highlight. */
function page(title, active, body, notice = "") {
  return `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)} · BEER Redaktion</title><style>
:root{--ink:#1d1d1b;--muted:#6b6760;--line:#e3ded6;--paper:#faf8f5;--card:#fff;--red:#a4161a;--amber:#7a5c00;--green:#2d6a4f}
*{box-sizing:border-box}body{font:15px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif;margin:0;color:var(--ink);background:var(--paper)}
nav{display:flex;flex-wrap:wrap;gap:4px 14px;padding:12px 16px;border-bottom:1px solid var(--line);background:var(--card);font-size:14px}
nav a{color:var(--muted);text-decoration:none}nav a.on{color:var(--ink);font-weight:600}nav b{margin-right:8px}
main{max-width:1080px;margin:0 auto;padding:24px 16px 64px}h1{font-weight:500;font-size:28px;margin:0 0 4px}
h2{font-size:19px;margin:28px 0 8px}h3{font-size:15px;margin:16px 0 6px}a{color:var(--ink)}
.small{font-size:13px;color:var(--muted)}.card{background:var(--card);border:1px solid var(--line);border-radius:6px;padding:16px 18px;margin:14px 0}
table{border-collapse:collapse;width:100%}td,th{vertical-align:top;text-align:left;padding:7px 8px;border-bottom:1px solid #ece8e1}th{font-weight:600;font-size:13px;color:var(--muted)}
ul{margin:0;padding-left:18px}.fehler{color:var(--red)}.hinweis{color:var(--amber)}.ok{color:var(--green)}
.kpi{display:flex;gap:28px;margin:16px 0 20px;flex-wrap:wrap}.kpi b{display:block;font-size:24px;font-weight:600}
.notice{background:#eef6f0;border:1px solid #b7d8c2;padding:8px 12px;border-radius:4px;margin:12px 0}
.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}form{margin:0;display:inline-flex;flex-wrap:wrap;gap:8px;align-items:center}
button{font:inherit;padding:7px 14px;border:1px solid var(--ink);background:#fff;border-radius:4px;cursor:pointer}button.primary{background:var(--ink);color:#fff}
input,select,textarea{font:inherit;padding:6px 8px;border:1px solid #cfc9bf;border-radius:4px;background:#fff}textarea{width:100%;min-height:90px}
dl{display:grid;grid-template-columns:160px 1fr;gap:4px 12px;margin:0}dt{color:var(--muted)}dd{margin:0}.pre{white-space:pre-wrap}
details>summary{cursor:pointer;padding:10px 0}img{border-radius:3px;display:block;max-width:100%}
@media (max-width:640px){dl{grid-template-columns:1fr}.kpi{gap:18px}}</style></head><body>
<nav><b>BEER Redaktion</b>${NAV.map(([label, href]) => `<a href="${href}"${label === active ? ' class="on"' : ""}>${esc(label)}</a>`).join("")}</nav>
<main><h1>${esc(title)}</h1>${notice ? `<p class="notice">${notice}</p>` : ""}${body}</main></body></html>`;
}

/** A small POST form with hidden fields and one button. */
function button(action, fields, label, primary = false) {
  const hidden = Object.entries(fields).map(([k, v]) => `<input type="hidden" name="${esc(k)}" value="${esc(v)}">`).join("");
  return `<form method="post" action="${esc(action)}">${hidden}<button${primary ? ' class="primary"' : ""}>${esc(label)}</button></form>`;
}

/* eslint-disable @typescript-eslint/no-unused-vars -- shared helpers, pasted in front of the Code nodes that use them */
/**
 * Shared by the n8n Code nodes that talk to Claude (pasted in by pack-workflows.mjs).
 * claudeRequest() builds a Messages API body; the HTTP node "… Claude" sends it with the
 * credential "Claude API (BEER)". claudeAnswer() reads the JSON answer back.
 */

const MODEL = "claude-opus-5-5";

/**
 * schema: JSON schema for structured output (strict JSON back).
 * webSearch: number of searches allowed; then the answer is asked for as a JSON block in the
 * text instead, since search results come back with citations.
 */
function claudeRequest({ system, user, schema, effort = "medium", maxTokens = 16000, webSearch = 0 }) {
  const request = {
    model: MODEL,
    max_tokens: maxTokens,
    system,
    output_config: { effort },
    // Lets the API answer with a fallback model when a request is declined.
    fallbacks: "default",
    messages: [{ role: "user", content: user }],
  };
  if (webSearch) {
    request.tools = [
      {
        type: "web_search_20260209",
        name: "web_search",
        max_uses: webSearch,
        user_location: { type: "approximate", city: "Freising", region: "Bayern", country: "DE", timezone: "Europe/Berlin" },
      },
    ];
    if (schema) {
      request.system += `\n\nAntworte am Ende ausschließlich mit einem JSON-Objekt nach diesem Schema, ohne weiteren Text:\n${JSON.stringify(schema)}`;
    }
  } else if (schema) {
    request.output_config.format = { type: "json_schema", schema };
  }
  return request;
}

/** { value } with the parsed JSON answer, or { error } when the call produced none. */
function claudeAnswer(response) {
  if (!response || response.type === "error" || response.error) {
    // After retries the HTTP node passes the failure on as { error: "…" } or { error: { message } }.
    const error = response?.error;
    const message = typeof error === "string" ? error : error?.message ?? response?.message ?? "keine Antwort";
    return { error: `Claude: ${message}` };
  }
  if (response.stop_reason === "refusal") return { error: "Claude hat abgelehnt." };
  if (response.stop_reason === "max_tokens") return { error: "Antwort abgeschnitten (max_tokens)." };
  if (response.stop_reason === "pause_turn") return { error: "Suche nicht fertig geworden – bitte erneut starten." };
  const text = (response.content ?? []).filter((block) => block.type === "text").map((block) => block.text).join("");
  for (const candidate of [text, text.match(/```(?:json)?\s*([\s\S]*?)```/)?.[1], text.slice(text.indexOf("{"), text.lastIndexOf("}") + 1)]) {
    if (!candidate) continue;
    try {
      return { value: JSON.parse(candidate), sources: webSources(response) };
    } catch {
      // try the next form
    }
  }
  return { error: "Antwort war kein gültiges JSON." };
}

/** The pages Claude's web searches returned (title and address), for reports. */
function webSources(response) {
  const seen = new Map();
  for (const block of response.content ?? []) {
    if (block.type !== "web_search_tool_result" || !Array.isArray(block.content)) continue;
    for (const hit of block.content) if (hit.url && !seen.has(hit.url)) seen.set(hit.url, hit.title ?? hit.url);
  }
  return [...seen].map(([url, title]) => ({ url, title }));
}

/** Short company facts every prompt may use; nothing beyond these may be invented. */
const BEER_FACTS = `BEER Küchenmanufaktur: Schreinerei und Küchenmanufaktur mit eigener Fertigung und Ausstellung in Wolfersdorf bei Freising (Bayern). Plant und baut Küchen und Möbel nach Maß für Kundinnen und Kunden im Raum München, Freising, Landshut und Umgebung. Arbeitet mit Geräten und Materialien unter anderem von Bora, Miele, Gaggenau, Siemens, Quooker und Fenix.`;

/* eslint-disable @typescript-eslint/no-unused-vars -- shared helpers, pasted in front of the Code nodes that use them */
/**
 * The SEO rules, shared by "BEER SEO-Prüfung" (report) and "BEER SEO-Vorschläge" (fixes).
 * Pasted in after lib-common.js. seoRows() takes the "Abfragen" items and the Strapi answers
 * in the same order and returns one row per German entry with its issues. Each issue has a
 * level (fehler = fix before publishing, hinweis = improvement) and a code.
 */

const SEO_TYPES = {
  projects: { label: "Projekte", path: (e) => `/projekte/${e.slug}`, seo: true },
  "kitchen-topics": { label: "Küchen-Themen", path: (e) => `/kuechen/${e.cluster}/${e.slug}`, seo: true },
  regions: { label: "Regionen", path: (e) => `/regionen/${e.slug}`, seo: true },
  materials: { label: "Material", path: (e) => `/material/${e.slug}`, seo: true },
  appliances: { label: "Geräte", path: (e) => `/geraete/${e.slug}`, seo: true },
  brands: { label: "Marken", path: (e) => `/marken/${e.slug}`, seo: true },
  "furniture-items": { label: "Möbel", path: (e) => `/moebel/${e.slug}`, seo: true },
  "site-pages": { label: "Feste Seiten", path: (e) => `/${e.slug}`, seo: false },
  articles: { label: "Artikel", path: (e) => `/${e.category?.slug === "presse" ? "presse" : "ratgeber"}/${e.slug}`, seo: false },
};

// Codes that "SEO-Vorschläge" can fix with a new meta title and description.
const META_CODES = ["meta-title-missing", "meta-title-long", "meta-desc-missing", "meta-desc-long", "meta-desc-short", "dup-title", "dup-desc"];

function seoRows(requests, answers) {
  const drafts = {};
  const published = {};
  const english = {};
  const failed = [];
  answers.forEach((answer, i) => {
    const request = requests[i];
    if (!request) return;
    if (!Array.isArray(answer?.data)) {
      failed.push(`${request.api} (${request.status}, ${request.locale}, Seite ${request.page})`);
      return;
    }
    for (const entry of answer.data) {
      if (request.locale === "en") (english[request.api] ??= new Set()).add(entry.documentId);
      else if (request.status === "published") (published[request.api] ??= new Map()).set(entry.documentId, entry.updatedAt);
      else (drafts[request.api] ??= []).push(entry);
    }
  });

  const len = (value) => String(value ?? "").trim().length;
  const all = [];
  for (const [api, entries] of Object.entries(drafts)) {
    const type = SEO_TYPES[api];
    if (!type) continue;
    for (const entry of entries) {
      const name = entry.title || entry.name || "";
      const issues = [];
      const add = (level, code, text) => issues.push({ level, code, text });

      if (!name) add("fehler", "title", "Titel fehlt.");
      if (!entry.slug) add("fehler", "slug", "Adresse (Slug) fehlt.");
      else if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(entry.slug))
        add("fehler", "slug", `Adresse „${entry.slug}“: nur a–z, 0–9 und Bindestriche (ä → ae, ß → ss).`);

      const live = published[api]?.get(entry.documentId);
      if (!live) add("hinweis", "unpublished", "Noch nicht veröffentlicht.");
      else if (new Date(entry.updatedAt) > new Date(live)) add("hinweis", "changed", "Entwurf geändert, noch nicht veröffentlicht.");

      const metaTitle = entry.seo?.metaTitle || "";
      const metaDescription = type.seo ? entry.seo?.metaDescription || "" : entry.intro || entry.description || "";
      if (type.seo) {
        if (!metaTitle) add("hinweis", "meta-title-missing", "Kein Meta-Titel – Google zeigt den Seitentitel.");
        else if (len(metaTitle) > 60) add("hinweis", "meta-title-long", `Meta-Titel hat ${len(metaTitle)} Zeichen – Google kürzt ab etwa 60.`);
        if (!metaDescription) add("fehler", "meta-desc-missing", "Meta-Beschreibung fehlt.");
        else if (len(metaDescription) > 160) add("fehler", "meta-desc-long", `Meta-Beschreibung hat ${len(metaDescription)} Zeichen – höchstens 160.`);
        else if (len(metaDescription) < 70) add("hinweis", "meta-desc-short", `Meta-Beschreibung hat nur ${len(metaDescription)} Zeichen – 120 bis 160 sind ideal.`);
      } else if (!metaDescription) {
        add("hinweis", "intro", "Keine Einleitung – Google bekommt keine Beschreibung dieser Seite.");
      }

      const cover = api === "articles" ? entry.cover : entry.image;
      if (!cover) add(api === "site-pages" ? "hinweis" : "fehler", "cover", "Kein Titelbild – auch kein Vorschaubild beim Teilen.");
      else if (weakAlt(cover.alternativeText)) add("hinweis", "cover-alt", "Titelbild ohne Beschreibung (Alt-Text).");

      if (api === "projects") {
        const gallery = entry.gallery ?? [];
        const missing = gallery.filter((photo) => weakAlt(photo.alternativeText)).length;
        if (gallery.length < 4) add("hinweis", "gallery", `Nur ${gallery.length} Fotos in der Galerie – mindestens 4 zeigen die Küche.`);
        if (missing) add("hinweis", "gallery-alt", `${missing} von ${gallery.length} Fotos ohne Beschreibung (Alt-Text).`);
        if (!entry.place) add("hinweis", "place", "Kein Ort angegeben.");
        else if (/^raum münchen$/i.test(entry.place.trim())) add("hinweis", "place", "Nur „Raum München“ – ein echter Ort hilft bei der lokalen Suche.");
        if (!entry.year) add("hinweis", "year", "Kein Jahr angegeben.");
        if (!entry.regions?.length) add("hinweis", "region", "Keine Region verknüpft – erscheint auf keiner Regionsseite.");
        if (!entry.topics?.length) add("hinweis", "topic", "Kein Thema (Stil, Farbe, Form) – erscheint auf keiner Themenseite.");
        if (len(entry.body) < 300) add("hinweis", "body", `Kurzer Text (${len(entry.body)} Zeichen) – 300 und mehr erzählen die Küche.`);
      } else if (!entry.intro && !entry.description) {
        add("fehler", "intro", "Einleitung fehlt.");
      }

      all.push({
        api,
        entry,
        name,
        live: Boolean(live),
        metaTitle: metaTitle || name,
        metaDescription,
        issues,
        english: english[api]?.has(entry.documentId) ?? false,
      });
    }
  }

  // Same title or description on two pages: Google cannot tell them apart.
  const groups = (key) => {
    const map = new Map();
    for (const row of all) {
      const value = String(row[key] ?? "").trim().toLowerCase();
      if (value) map.set(value, [...(map.get(value) ?? []), row]);
    }
    return [...map.values()].filter((rows) => rows.length > 1);
  };
  for (const rows of groups("metaTitle"))
    for (const row of rows)
      row.issues.push({ level: "fehler", code: "dup-title", text: `Gleicher Titel wie: ${rows.filter((r) => r !== row).map((r) => r.name).join(", ")}.` });
  for (const rows of groups("metaDescription"))
    for (const row of rows)
      row.issues.push({ level: "hinweis", code: "dup-desc", text: `Gleiche Beschreibung wie: ${rows.filter((r) => r !== row).map((r) => r.name).join(", ")}.` });

  return { all, failed };
}

/**
 * n8n Code node "Seite" (workflow "BEER SEO-Vorschläge"): old and new snippet side by side.
 */

const BASE = "/webhook/seo-vorschlaege";
const store = $getWorkflowStaticData("global");
const query = $input.first()?.json?.query ?? {};
const proposals = Object.values(store.proposals ?? {}).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
const open = proposals.filter((p) => p.status === "offen" || p.status === "speichert");
const done = proposals.filter((p) => p.status === "übernommen").slice(0, 40);

// A Google-like preview of the snippet.
const snippet = (title, description, path) => `<div style="font-family:arial,sans-serif;max-width:600px">
<div style="color:#1a0dab;font-size:18px;line-height:1.3">${esc(title)}</div>
<div style="color:#006621;font-size:13px">beer.de${esc(path)}</div>
<div style="color:#4d5156;font-size:14px">${esc(description)}</div></div>`;

const card = (p) => `<section class="card"><b><a href="${esc(adminUrl(p.api, p.documentId))}" target="_blank">${esc(p.name)}</a></b>
<span class="small">· ${esc(SEO_TYPES[p.api]?.label ?? p.api)}${p.live ? "" : " · noch nicht veröffentlicht"}</span>
<div class="hinweis small">${p.issues.map(esc).join(" ")}</div>
<table><tr><th>Bisher</th><th>Vorschlag</th></tr><tr><td>${snippet(p.old.metaTitle || p.name, p.old.metaDescription, p.path)}</td>
<td>${snippet(p.new.metaTitle, p.new.metaDescription, p.path)}<div class="small">${p.new.metaTitle.length} / ${p.new.metaDescription.length} Zeichen</div></td></tr></table>
${p.warnings?.length ? `<p class="hinweis">${p.warnings.map(esc).join(" ")}</p>` : ""}${p.error ? `<p class="fehler">${esc(p.error)}</p>` : ""}
${p.status === "offen" ? `<div class="actions">${button(`${BASE}/aktion`, { documentId: p.documentId, aktion: "uebernehmen" }, "Übernehmen", true)}${button(`${BASE}/aktion`, { documentId: p.documentId, aktion: "verwerfen" }, "Verwerfen")}</div>` : `<p class="small">Wird gespeichert …</p>`}</section>`;

const notice = query.gestartet
  ? "Vorschläge werden erstellt – etwa eine Minute. Seite danach neu laden."
  : query.gespeichert
    ? "Wird in Strapi gespeichert. Die Änderung steht dann als Entwurf bereit und wird in Strapi veröffentlicht."
    : "";

const html = page(
  "SEO-Vorschläge",
  "SEO-Vorschläge",
  `<p class="small">Für Einträge, bei denen die SEO-Prüfung Titel oder Beschreibung bemängelt (fehlt, zu lang, doppelt), schreibt Claude neue Snippets. „Übernehmen“ speichert sie in den <b>Entwurf</b> des Eintrags; veröffentlicht wird in Strapi.</p>
<section class="card"><div class="actions">${button(`${BASE}/erstellen`, {}, "Vorschläge für bis zu 15 Einträge erstellen", true)}
${open.length > 1 ? button(`${BASE}/aktion`, { documentId: "alle", aktion: "uebernehmen" }, `Alle ${open.length} übernehmen`) : ""}</div></section>
<h2>Offen (${open.length})</h2>${open.map(card).join("") || `<p class="small">Keine offenen Vorschläge.</p>`}
${done.length ? `<h2>Übernommen – in Strapi veröffentlichen</h2><table>${done.map((p) => `<tr><td><a href="${esc(adminUrl(p.api, p.documentId))}" target="_blank">${esc(p.name)}</a></td><td>${esc(p.new.metaTitle)}<div class="small">${esc(when(p.doneAt))}</div>${p.error ? `<div class="fehler">${esc(p.error)}</div>` : ""}</td></tr>`).join("")}</table>` : ""}
${(store.log ?? []).length ? `<details><summary class="small">Verlauf</summary><ul class="small">${store.log.slice(0, 15).map((l) => `<li>${esc(when(l.at))}: ${esc(l.text)}</li>`).join("")}</ul></details>` : ""}`,
  notice,
);
return [{ json: { html } }];

/* eslint-disable @typescript-eslint/no-unused-vars -- shared helpers, pasted in front of the Code nodes that use them */
/**
 * Shared helpers, pasted by pack-workflows.mjs in front of every Code node that needs them:
 * addresses, query strings, escaping, slugs, Strapi admin links, and the one page layout
 * with navigation used by all review pages. Nothing here talks to an API.
 */

const CMS = "https://cms.beer.de";
// Links to the website go to staging until the new site is live on beer.de.
const SITE = "https://staging.beer.de";

const qs = (query) =>
  Object.entries(query)
    .filter(([, value]) => value !== undefined && value !== null)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
    .join("&");

const esc = (value) =>
  String(value ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

const slugify = (value, max = 60) =>
  String(value ?? "")
    .toLowerCase()
    .replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, max)
    .replace(/-$/, "");

const UID = {
  projects: "api::project.project",
  articles: "api::article.article",
  "site-pages": "api::site-page.site-page",
  "kitchen-topics": "api::kitchen-topic.kitchen-topic",
  regions: "api::region.region",
  materials: "api::material.material",
  appliances: "api::appliance.appliance",
  brands: "api::brand.brand",
  "furniture-items": "api::furniture-item.furniture-item",
};
const adminUrl = (api, documentId, locale = "de") =>
  `${CMS}/admin/content-manager/collection-types/${UID[api] ?? api}/${documentId}?plugins[i18n][locale]=${locale}`;

const when = (iso) => (iso ? new Date(iso).toLocaleString("de-DE", { timeZone: "Europe/Berlin", dateStyle: "medium", timeStyle: "short" }) : "");

// Same words as the website uses for a "useful" photo description.
